{
  "bbb_prediction": "pass",
  "claims": [
    {
      "card_ids": ["C20"],
      "claim": "In mice, the N-ethylthiourea analogue HI-236 reached brain concentrations comparable to plasma, directly showing that an ethylthiourea/heteroaryl scaffold can cross the BBB; this is the highest-similarity analogue and supports meaningful CNS access for the query's thiourea-containing core.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C14"],
      "claim": "A second N-ethylthiourea analogue (HI-240) also showed brain concentrations comparable to plasma in mice, reinforcing that the ethylthiourea substructure is compatible with BBB penetration.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C07"],
      "claim": "The diethylaminoethyl-pyridine radioligand [18F]2 showed good brain uptake (>4% ID/g at 2 min) in mice, demonstrating that a protonatable tertiary amine plus heteroaromatic system can still achieve meaningful brain penetration.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C01"],
      "claim": "NE-100, which contains the same dipropylaminoalkyl basic motif, was taken up into brain in a PET study, supporting that the dipropylamine group does not inherently prevent CNS access.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C10"],
      "claim": "Ethyl thiourea itself penetrated nervous tissue to levels higher than CSF, providing direct substructure-level evidence that the N-ethylthiourea group is CNS-permeable.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C18"],
      "claim": "AF-DX384, which shares the dipropylaminomethyl group, was reported to have low BBB penetration; however, it is a much larger, more complex molecule, so this negative result transfers only weakly to the smaller query.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "Multiple independent experimental analogues show that the key substructures in the query—ethylthiourea, heteroaromatic imidazole/pyrimidine, and dipropylaminoalkyl—are each compatible with BBB penetration. The main negative analogue is larger and less transferable, while the query's physicochemical properties are moderate. Overall, meaningful CNS access is more likely than not.",
  "evidence_gaps": [
    "No direct brain/plasma or CSF measurement for the exact query molecule; all analogues have Morgan similarity below 0.22.",
    "No experimental P-gp/BCRP efflux data for the query or close analogues; transporter liability remains uncertain.",
    "Species differences in BBB penetration (e.g., lansoprazole analogue) create uncertainty in extrapolating rodent and human data."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

